def count_ways(n):
    # Calculate the total number of ways to distribute coins without any restrictions
    total_ways = pow(3, 3*n, MOD)

    # Calculate the number of invalid distributions
    invalid_ways = 0

    # Iterate over all possible values for a_i, a_{i+n}, and a_{i+2n}
    for a in range(1, 4):
        for b in range(1, 4):
            for c in range(1, 4):
                if a + a + n + b + 2*n != 6:
                    continue
                if b + b + n + c + 2*n != 6:
                    continue
                if c + c + n + a + 2*n != 6:
                    continue
                invalid_ways += 1

    # Subtract the number of invalid distributions from the total ways
    valid_ways = (total_ways - invalid_ways * pow(3, 2*n, MOD)) % MOD

    return valid_ways

