def count_ways(n):
    dp = [[[[0] * 4 for _ in range(4)] for _ in range(4)] for _ in range(4)]
    dp[1][1][1][1] = 1

    for k in range(1, n+1):
        ndp = [[[[0] * 4 for _ in range(4)] for _ in range(4)] for _ in range(4)]
        for a1 in range(1, 4):
            for a2 in range(1, 4):
                for a3 in range(1, 4):
                    for c1 in range(4):
                        for c2 in range(4):
                            for c3 in range(4):
                                if a1 + a2 + n + a3 + 2*n == 6:
                                    continue
                                next_c1 = (c1 + a1) % 4
                                next_c2 = (c2 + a2) % 4
                                next_c3 = (c3 + a3) % 4
                                ndp[next_c1][next_c2][next_c3][k % 4] += dp[c1][c2][c3][(k-1) % 4]
                                ndp[next_c1][next_c2][next_c3][k % 4] %= MOD
        dp = ndp

    total_ways = sum(dp[c1][c2][c3][n % 4] for c1 in range(4) for c2 in range(4) for c3 in range(4))
    return total_ways % MOD

